import ast
import json
from collections import Counter
def task_func(file_pointer):
    data = json.load(file_pointer)
    counter = Counter()

    for item in data:
        if isinstance(item, str):
            obj = ast.literal_eval(item)
        else:
            obj = item

        if isinstance(obj, dict):
            counter.update(obj.keys())

    return counter

